import json, sys, time, urllib.request, urllib.error
from datetime import datetime, timezone
from decimal import Decimal

BASE = "http://localhost:8080"
START = datetime(2025, 3, 1, tzinfo=timezone.utc)
END_EXCL = datetime(2025, 6, 1, tzinfo=timezone.utc)  # 31 May inclusive

state = {"token": None}
log = lambda *a: print(*a, file=sys.stderr, flush=True)

def raw(method, path, auth=False):
    headers = {}
    if auth:
        headers["Authorization"] = "Bearer " + state["token"]
    req = urllib.request.Request(BASE + path, method=method, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            return r.status, dict(r.headers), r.read().decode()
    except urllib.error.HTTPError as e:
        return e.code, dict(e.headers), e.read().decode(errors="replace")

def get_token():
    code, h, body = raw("POST", "/token")
    if code != 200:
        raise RuntimeError(f"token failed {code} {body[:200]}")
    state["token"] = json.loads(body)["token"]
    log("new token", state["token"])

def call(path, auth=True, max_attempts=50):
    """GET with retry on 401 (refresh token), 429 (honour wait), 5xx/network (backoff)."""
    attempt = 0
    while True:
        attempt += 1
        if attempt > max_attempts:
            raise RuntimeError(f"gave up on {path} after {max_attempts} attempts")
        if auth and state["token"] is None:
            get_token()
        try:
            code, h, body = raw("GET", path, auth=auth)
        except Exception as e:
            log(f"network error {path}: {e}; retrying")
            time.sleep(min(2 ** attempt, 30))
            continue
        if code == 200:
            return json.loads(body)
        log(f"HTTP {code} on {path} attempt {attempt}: headers={ {k: v for k, v in h.items() if k.lower() in ('retry-after','www-authenticate','x-ratelimit-reset','x-ratelimit-remaining')} } body={body[:300]!r}")
        if code == 401 and auth:
            get_token()
            continue
        if code == 429:
            ra = h.get("Retry-After")
            wait = None
            if ra is not None:
                try:
                    wait = float(ra)
                except ValueError:
                    wait = None
            if wait is None:
                try:
                    wait = float(json.loads(body).get("retry_after", 0)) or None
                except Exception:
                    wait = None
            wait = wait if wait is not None else 5
            log(f"rate limited; sleeping {wait}s")
            time.sleep(wait + 0.5)
            continue
        if code == 404 and not auth:
            raise RuntimeError(f"404 on {path}")
        if code == 404:
            return {"__404__": True}
        time.sleep(min(2 ** attempt, 30))

if __name__ == "__main__":
    out = sys.argv[1]
    listings = []   # every listing row, in order, with page number
    page = 1
    total_pages = None
    while True:
        data = call(f"/orders?page={page}")
        total_pages = data["total_pages"]
        for it in data["items"]:
            listings.append({"page": data["page"], **it})
        log(f"page {page}/{total_pages} items={len(data['items'])} next={data['next']}")
        if data["next"] is None:
            break
        page += 1
    with open(out, "w") as f:
        json.dump({"total_pages": total_pages, "listings": listings}, f)
    log(f"done: pages={page} listings={len(listings)}")
EOF
cd /tmp/recon && timeout 900 python3 fetch.py /tmp/recon/listings.json 2> /tmp/recon/fetch.log; echo "exit=$?"; tail -n 40 /tmp/recon/fetch.log

